import sys
import heapq

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    intervals = []
    for _ in range(m):
        x = int(next(it))
        y = int(next(it))
        L = x if x < y else y
        R = x if x > y else y
        intervals.append((L, R))

    # 按左端点升序排序
    intervals.sort(key=lambda seg: seg[0])

    pq = []          # 小根堆，存放右端点
    ans = 0
    idx = 0
    for i in range(1, n + 1):
        # 将所有 L <= i 的区间入堆
        while idx < m and intervals[idx][0] <= i:
            heapq.heappush(pq, intervals[idx][1])
            idx += 1
        # 移除右端点小于 i 的过期区间
        while pq and pq[0] < i:
            heapq.heappop(pq)
        # 匹配当前避难所
        if pq:
            heapq.heappop(pq)
            ans += 1

    sys.stdout.write(str(ans))

if __name__ == "__main__":
    main()
